import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

export default function Dashboard() {
  const navigate = useNavigate();
  const [user, setUser] = useState(null);
  const [sessions, setSessions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showAchievement, setShowAchievement] = useState(false);
  const [filterSubject, setFilterSubject] = useState('all');
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    loadUserData();
    loadSessions();
  }, []);

  useEffect(() => {
    if (sessions.length >= 5 && !localStorage.getItem('achievement_5sessions')) {
      setShowAchievement(true);
      localStorage.setItem('achievement_5sessions', 'true');
      setTimeout(() => setShowAchievement(false), 5000);
    }
  }, [sessions.length]);

  const loadUserData = () => {
    const userData = localStorage.getItem('currentUser');
    if (userData) {
      setUser(JSON.parse(userData));
    }
  };

  const loadSessions = async () => {
    try {
      const token = localStorage.getItem('authToken');
      if (!token) {
        console.log('No token found');
        setLoading(false);
        return;
      }

      const response = await fetch('http://localhost:8000/api/sessions', {
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        }
      });

      if (response.ok) {
        const data = await response.json();
        console.log('✅ Sessions loaded:', data);
        setSessions(data);
      } else {
        console.error('❌ Failed to load sessions:', response.status);
      }
    } catch (error) {
      console.error('❌ Error loading sessions:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = () => {
    localStorage.clear();
    navigate('/auth', { replace: true });
  };

  const handleStartSession = (tutorId, subject) => {
    const roomId = `room_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
    console.log('🚀 Starting NEW session with tutorId:', tutorId, 'subject:', subject);
    navigate(`/video/${roomId}`, { 
      state: { 
        tutorId: tutorId, 
        subject: subject, 
        resuming: false 
      },
      replace: true
    });
  };

  const handleResumeSession = (session) => {
    navigate(`/video/${session.session_id}`, { 
      state: { 
        tutorId: session.tutor_id,
        subject: session.subject, 
        resuming: true 
      },
      replace: true
    });
  };

  const tutors = [
    { 
      id: 'omkar_ai',
      name: 'Omkar', 
      subject: 'AI & Machine Learning', 
      description: 'Expert in Artificial Intelligence and Machine Learning', 
      specialty: 'Neural Networks, Deep Learning, NLP',
      rating: 4.9,
      students: 234
    },
    { 
      id: 'priya_biology',
      name: 'Priya', 
      subject: 'Biology', 
      description: 'Passionate Biology tutor specializing in life sciences', 
      specialty: 'Genetics, Cell Biology, Physiology',
      rating: 4.8,
      students: 189
    }
  ];

  // Calculate total study hours (assuming each session is ~30 mins on average, you can modify based on actual duration data)
  const calculateStudyHours = () => {
    // If you have actual duration in your session data, use: sessions.reduce((sum, s) => sum + (s.duration || 0), 0)
    // For now, estimating 30 mins per session as placeholder
    const totalMinutes = sessions.reduce((sum, session) => {
      // If your backend stores duration_minutes, use it: return sum + (session.duration_minutes || 30);
      return sum + 30; // Default 30 mins per session
    }, 0);
    return (totalMinutes / 60).toFixed(1);
  };

  const totalMessages = sessions.reduce((sum, session) => sum + session.message_count, 0);
  const streak = Math.min(sessions.length, 7);
  const totalHours = calculateStudyHours();

  // Subject breakdown
  const subjectStats = sessions.reduce((acc, session) => {
    const subject = session.tutor_id === 'omkar_ai' ? 'AI & ML' : 'Biology';
    acc[subject] = (acc[subject] || 0) + 1;
    return acc;
  }, {});

  // Filter sessions
  const filteredSessions = sessions.filter(session => {
    const matchesSubject = filterSubject === 'all' || 
      (filterSubject === 'ai' && session.tutor_id === 'omkar_ai') ||
      (filterSubject === 'bio' && session.tutor_id === 'priya_biology');

    const matchesSearch = searchTerm === '' || 
      session.tutor_id.toLowerCase().includes(searchTerm.toLowerCase());

    return matchesSubject && matchesSearch;
  });

  // Get last 7 days activity
  const getLast7DaysActivity = () => {
    const last7Days = Array.from({ length: 7 }, (_, i) => {
      const date = new Date();
      date.setDate(date.getDate() - (6 - i));
      return date.toISOString().split('T')[0];
    });

    return last7Days.map(date => {
      const count = sessions.filter(s => 
        new Date(s.created_at).toISOString().split('T')[0] === date
      ).length;
      return { date, count };
    });
  };

  const weeklyActivity = getLast7DaysActivity();

  return (
    <div className="flex min-h-screen bg-slate-900">

      {/* Achievement Toast */}
      {showAchievement && (
        <div className="fixed top-6 right-6 z-50 bg-slate-800 border border-slate-700 rounded-lg shadow-2xl px-5 py-4 max-w-sm animate-bounce">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-green-900/30 border border-green-700 rounded-lg flex items-center justify-center">
              <svg className="w-5 h-5 text-green-400" fill="currentColor" viewBox="0 0 20 20">
                <path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z" />
              </svg>
            </div>
            <div>
              <div className="font-semibold text-slate-100 text-sm">Achievement Unlocked</div>
              <div className="text-xs text-slate-400 mt-0.5">Completed 5 sessions</div>
            </div>
          </div>
        </div>
      )}

      {/* Sidebar */}
      <aside className="w-72 bg-slate-950 border-r border-slate-800 flex flex-col">
        <div className="p-6 border-b border-slate-800">
          <h1 className="text-2xl font-bold text-slate-100">Saarthi</h1>
          <p className="text-xs text-slate-500 mt-1">AI Learning Platform</p>
        </div>

        <div className="flex-1 p-4">
          <nav className="space-y-2">
            <button className="w-full flex items-center gap-3 px-4 py-3 bg-slate-800 text-slate-100 rounded-lg font-medium text-sm">
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6" />
              </svg>
              Dashboard
            </button>
            <button className="w-full flex items-center gap-3 px-4 py-3 text-slate-400 hover:text-slate-200 hover:bg-slate-900 rounded-lg font-medium text-sm transition-colors">
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
              </svg>
              My Sessions
            </button>
            <button className="w-full flex items-center gap-3 px-4 py-3 text-slate-400 hover:text-slate-200 hover:bg-slate-900 rounded-lg font-medium text-sm transition-colors">
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
              </svg>
              Progress
            </button>
          </nav>

          {/* Quick Stats in Sidebar */}
          <div className="mt-6 p-4 bg-slate-900 rounded-lg border border-slate-800">
            <div className="text-xs text-slate-500 mb-3 font-medium">This Week</div>
            <div className="space-y-3">
              <div className="flex items-center justify-between">
                <span className="text-xs text-slate-400">Sessions</span>
                <span className="text-sm font-bold text-slate-200">{sessions.filter(s => {
                  const sessionDate = new Date(s.created_at);
                  const weekAgo = new Date();
                  weekAgo.setDate(weekAgo.getDate() - 7);
                  return sessionDate >= weekAgo;
                }).length}</span>
              </div>
              <div className="flex items-center justify-between">
                <span className="text-xs text-slate-400">Hours</span>
                <span className="text-sm font-bold text-slate-200">{totalHours}h</span>
              </div>
            </div>
          </div>
        </div>

        <div className="p-4 border-t border-slate-800">
          <div className="flex items-center gap-3 px-4 py-3 bg-slate-900 rounded-lg mb-3">
            <div className="w-10 h-10 bg-slate-700 rounded-lg flex items-center justify-center text-slate-200 font-semibold">
              {user?.name?.charAt(0)?.toUpperCase() || 'S'}
            </div>
            <div className="flex-1 min-w-0">
              <div className="text-sm font-semibold text-slate-200 truncate">{user?.name || 'Student'}</div>
              <div className="text-xs text-slate-500 truncate">{user?.email}</div>
            </div>
          </div>
          <button 
            onClick={handleLogout}
            className="w-full px-4 py-2.5 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-lg font-medium text-sm transition-colors flex items-center justify-center gap-2"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
            </svg>
            Logout
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto">
        <div className="p-8">

          {/* Header */}
          <div className="mb-8">
            <h2 className="text-3xl font-bold text-slate-100 mb-2">
              Welcome back, {user?.name || 'Student'}
            </h2>
            <p className="text-slate-400">Continue your learning journey</p>
          </div>

          {/* Stats Grid */}
          <div className="grid grid-cols-1 md:grid-cols-4 gap-5 mb-8">
            <div className="bg-slate-800/50 border border-slate-700 rounded-xl p-6 hover:border-slate-600 transition-colors">
              <div className="flex items-center justify-between mb-3">
                <div className="w-11 h-11 bg-blue-900/30 border border-blue-800 rounded-lg flex items-center justify-center">
                  <svg className="w-6 h-6 text-blue-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                  </svg>
                </div>
              </div>
              <div className="text-3xl font-bold text-slate-100 mb-1">{sessions.length}</div>
              <div className="text-sm text-slate-400">Sessions Completed</div>
            </div>

            <div className="bg-slate-800/50 border border-slate-700 rounded-xl p-6 hover:border-slate-600 transition-colors">
              <div className="flex items-center justify-between mb-3">
                <div className="w-11 h-11 bg-purple-900/30 border border-purple-800 rounded-lg flex items-center justify-center">
                  <svg className="w-6 h-6 text-purple-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" />
                  </svg>
                </div>
              </div>
              <div className="text-3xl font-bold text-slate-100 mb-1">{totalMessages}</div>
              <div className="text-sm text-slate-400">Messages Exchanged</div>
            </div>

            <div className="bg-slate-800/50 border border-slate-700 rounded-xl p-6 hover:border-slate-600 transition-colors">
              <div className="flex items-center justify-between mb-3">
                <div className="w-11 h-11 bg-orange-900/30 border border-orange-800 rounded-lg flex items-center justify-center">
                  <svg className="w-6 h-6 text-orange-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                  </svg>
                </div>
              </div>
              <div className="text-3xl font-bold text-slate-100 mb-1">{totalHours}</div>
              <div className="text-sm text-slate-400">Hours Studied</div>
            </div>

            <div className="bg-slate-800/50 border border-slate-700 rounded-xl p-6 hover:border-slate-600 transition-colors">
              <div className="flex items-center justify-between mb-3">
                <div className="w-11 h-11 bg-green-900/30 border border-green-800 rounded-lg flex items-center justify-center">
                  <svg className="w-6 h-6 text-green-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17.657 18.657A8 8 0 016.343 7.343S7 9 9 10c0-2 .5-5 2.986-7C14 5 16.09 5.777 17.656 7.343A7.975 7.975 0 0120 13a7.975 7.975 0 01-2.343 5.657z" />
                  </svg>
                </div>
              </div>
              <div className="text-3xl font-bold text-slate-100 mb-1">{streak}</div>
              <div className="text-sm text-slate-400">Day Streak</div>
            </div>
          </div>

          {/* Weekly Activity Chart */}
          <div className="bg-slate-800/50 border border-slate-700 rounded-xl p-6 mb-8">
            <h3 className="text-lg font-bold text-slate-100 mb-4">Weekly Activity</h3>
            <div className="flex items-end justify-between gap-2 h-32">
              {weeklyActivity.map((day, idx) => {
                const maxCount = Math.max(...weeklyActivity.map(d => d.count), 1);
                const height = (day.count / maxCount) * 100;
                const dayName = new Date(day.date).toLocaleDateString('en-US', { weekday: 'short' });

                return (
                  <div key={idx} className="flex-1 flex flex-col items-center gap-2">
                    <div className="w-full bg-slate-700 rounded-t relative overflow-hidden" style={{ height: height > 0 ? `${height}%` : '4px' }}>
                      {day.count > 0 && (
                        <div className="absolute inset-0 bg-gradient-to-t from-blue-600 to-blue-400"></div>
                      )}
                    </div>
                    <div className="text-xs text-slate-400">{dayName}</div>
                    <div className="text-xs font-semibold text-slate-300">{day.count}</div>
                  </div>
                );
              })}
            </div>
          </div>

          {/* Subject Breakdown */}
          {Object.keys(subjectStats).length > 0 && (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-5 mb-8">
              {Object.entries(subjectStats).map(([subject, count]) => (
                <div key={subject} className="bg-slate-800/50 border border-slate-700 rounded-xl p-6">
                  <div className="flex items-center justify-between mb-3">
                    <h4 className="text-base font-bold text-slate-100">{subject}</h4>
                    <span className="text-2xl font-bold text-slate-300">{count}</span>
                  </div>
                  <div className="w-full bg-slate-700 h-2 rounded-full overflow-hidden">
                    <div 
                      className="h-full bg-gradient-to-r from-blue-600 to-purple-600 rounded-full transition-all" 
                      style={{ width: `${(count / sessions.length) * 100}%` }}
                    ></div>
                  </div>
                  <div className="text-xs text-slate-400 mt-2">
                    {((count / sessions.length) * 100).toFixed(0)}% of total sessions
                  </div>
                </div>
              ))}
            </div>
          )}

          {/* AI Tutors Section */}
          <div className="mb-8">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-xl font-bold text-slate-100">AI Tutors</h3>
              <span className="flex items-center gap-2 text-sm text-green-400">
                <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
                {tutors.length} Online
              </span>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-5">
              {tutors.map((tutor) => (
                <div 
                  key={tutor.id}
                  className="bg-slate-800/50 border border-slate-700 hover:border-slate-600 rounded-xl p-6 transition-all duration-200 group"
                >
                  <div className="flex items-start justify-between mb-4">
                    <div className="flex-1">
                      <div className="flex items-center gap-3 mb-2">
                        <h4 className="text-lg font-bold text-slate-100">{tutor.name}</h4>
                        <div className="flex items-center gap-1 text-xs">
                          <svg className="w-4 h-4 text-yellow-500" fill="currentColor" viewBox="0 0 20 20">
                            <path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z" />
                          </svg>
                          <span className="text-slate-300 font-semibold">{tutor.rating}</span>
                        </div>
                      </div>
                      <p className="text-sm font-medium text-slate-400 mb-2">{tutor.subject}</p>
                      <p className="text-sm text-slate-500 leading-relaxed mb-3">{tutor.description}</p>
                      <div className="flex items-center gap-4 text-xs text-slate-400">
                        <span className="flex items-center gap-1">
                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" />
                          </svg>
                          {tutor.students} students
                        </span>
                      </div>
                    </div>
                    <div className="flex-shrink-0 w-14 h-14 bg-slate-700 rounded-xl border border-slate-600"></div>
                  </div>

                  <div className="mb-4 pt-4 border-t border-slate-700">
                    <div className="text-xs text-slate-500 mb-1">Specialties</div>
                    <div className="text-sm text-slate-300">{tutor.specialty}</div>
                  </div>

                  <button
                    onClick={() => handleStartSession(tutor.id, tutor.subject)}
                    className="w-full px-4 py-3 bg-slate-700 hover:bg-slate-600 text-slate-100 rounded-lg font-semibold text-sm transition-all duration-200 flex items-center justify-center gap-2 group-hover:shadow-lg"
                  >
                    Start New Session
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7l5 5m0 0l-5 5m5-5H6" />
                    </svg>
                  </button>
                </div>
              ))}
            </div>
          </div>

          {/* Recent Sessions with Filters */}
          <div>
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-xl font-bold text-slate-100">Recent Activity</h3>
              <div className="flex items-center gap-3">
                {/* Search */}
                <div className="relative">
                  <input
                    type="text"
                    placeholder="Search sessions..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="pl-10 pr-4 py-2 bg-slate-800 border border-slate-700 rounded-lg text-sm text-slate-200 placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-slate-600 w-48"
                  />
                  <svg className="w-4 h-4 text-slate-500 absolute left-3 top-1/2 -translate-y-1/2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                  </svg>
                </div>

                {/* Filter Buttons */}
                <div className="flex gap-2">
                  <button
                    onClick={() => setFilterSubject('all')}
                    className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                      filterSubject === 'all'
                        ? 'bg-slate-700 text-slate-100'
                        : 'bg-slate-800 text-slate-400 hover:text-slate-200'
                    }`}
                  >
                    All
                  </button>
                  <button
                    onClick={() => setFilterSubject('ai')}
                    className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                      filterSubject === 'ai'
                        ? 'bg-slate-700 text-slate-100'
                        : 'bg-slate-800 text-slate-400 hover:text-slate-200'
                    }`}
                  >
                    AI & ML
                  </button>
                  <button
                    onClick={() => setFilterSubject('bio')}
                    className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                      filterSubject === 'bio'
                        ? 'bg-slate-700 text-slate-100'
                        : 'bg-slate-800 text-slate-400 hover:text-slate-200'
                    }`}
                  >
                    Biology
                  </button>
                </div>
              </div>
            </div>

            {loading ? (
              <div className="flex flex-col items-center justify-center py-16 bg-slate-800/30 border border-slate-700 rounded-xl">
                <div className="relative w-12 h-12 mb-4">
                  <div className="absolute inset-0 border-4 border-slate-700 rounded-full"></div>
                  <div className="absolute inset-0 border-4 border-t-slate-400 rounded-full animate-spin"></div>
                </div>
                <p className="text-slate-400 font-medium">Loading sessions...</p>
              </div>
            ) : filteredSessions.length === 0 ? (
              <div className="bg-slate-800/30 border border-slate-700 rounded-xl p-12 text-center">
                <div className="w-16 h-16 bg-slate-800 rounded-full flex items-center justify-center mx-auto mb-4 border border-slate-700">
                  <svg className="w-8 h-8 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
                  </svg>
                </div>
                <h4 className="text-lg font-semibold text-slate-200 mb-2">
                  {sessions.length === 0 ? 'No sessions yet' : 'No matching sessions'}
                </h4>
                <p className="text-slate-400 text-sm">
                  {sessions.length === 0 
                    ? 'Start learning with an AI tutor to see your activity here'
                    : 'Try adjusting your filters or search term'}
                </p>
              </div>
            ) : (
              <div className="space-y-3">
                {filteredSessions.map((session) => {
                  const tutorName = session.tutor_id === 'omkar_ai' ? 'Omkar' : 'Priya';
                  const subject = session.tutor_id === 'omkar_ai' ? 'AI & ML' : 'Biology';

                  return (
                    <div 
                      key={session.session_id}
                      className="bg-slate-800/50 border border-slate-700 hover:border-slate-600 rounded-xl p-5 transition-all duration-200 group"
                    >
                      <div className="flex items-center justify-between">
                        <div className="flex items-center gap-4 flex-1">
                          <div className="w-12 h-12 bg-slate-700 border border-slate-600 rounded-lg flex items-center justify-center flex-shrink-0">
                            <span className="text-slate-300 font-bold text-lg">
                              {tutorName.charAt(0)}
                            </span>
                          </div>
                          <div className="flex-1 min-w-0">
                            <h4 className="text-base font-semibold text-slate-100 mb-1">
                              {tutorName} - {subject}
                            </h4>
                            <div className="flex items-center gap-4 text-sm text-slate-400">
                              <span className="flex items-center gap-1.5">
                                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
                                </svg>
                                {new Date(session.created_at).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}
                              </span>
                              <span className="flex items-center gap-1.5">
                                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" />
                                </svg>
                                {session.message_count} messages
                              </span>
                              <span className="flex items-center gap-1.5">
                                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                                </svg>
                                ~30 mins
                              </span>
                            </div>
                          </div>
                        </div>
                        <button
                          onClick={() => handleResumeSession(session)}
                          className="px-5 py-2.5 bg-slate-700 hover:bg-slate-600 text-slate-100 rounded-lg font-semibold text-sm transition-all duration-200 flex items-center gap-2 flex-shrink-0"
                        >
                          Resume
                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14.752 11.168l-3.197-2.132A1 1 0 0010 9.87v4.263a1 1 0 001.555.832l3.197-2.132a1 1 0 000-1.664z" />
                          </svg>
                        </button>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </div>
      </main>
    </div>
  );
}
